const n={loading:n=>{const{normalize:r}=n;return r(["ஏற்றுகிறது"])},Ranking:n=>{const{normalize:r}=n;return r(["தரவரிசை"])},Daily:n=>{const{normalize:r}=n;return r(["தினமும்"])},Weekly:n=>{const{normalize:r}=n;return r(["வாரந்தோறும்"])},Monthly:n=>{const{normalize:r}=n;return r(["மாதந்தோறும்"])},Duration:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["நேர காலம் ",t(o("duration"))])},OnlyShowTop:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["தரவரிசைப் பட்டியல் டாப் ",t(o("num"))," -ஐ மட்டும் காட்டுகிறது"])},i_got_it:n=>{const{normalize:r}=n;return r(["பெறுக"])},levelCount:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["Lv.",t(o("count"))])},honor:n=>{const{normalize:r}=n;return r(["ஹானர்"])},charm:n=>{const{normalize:r}=n;return r(["சார்ம்"])},room:n=>{const{normalize:r}=n;return r(["அறை"])},honor_tip:n=>{const{normalize:r}=n;return r(["நீங்கள் அனுப்பும் காயின்களின் எண்ணிக்கையைப் பொறுத்து ஹானர் தரவரிசை தீர்மானிக்கப்படுகிறது, அதிர்ஷ்டப் பரிசானது காயின்களின் மதிப்பில் 20% மட்டுமே கணக்கிடப்படும்."])},charm_tip:n=>{const{normalize:r}=n;return r(["நீங்கள் பெற்ற டைமண்ட்களின் எண்ணிக்கையைப் பொறுத்து சார்ம் தரவரிசை தீர்மானிக்கப்படுகிறது, அதிர்ஷ்டப் பரிசானது டைமண்ட்களின் மதிப்பில் 20% மட்டுமே கணக்கிடப்படும்."])},room_tip:n=>{const{normalize:r}=n;return r(["அறையில் பெறப்பட்ட காயின்களின் எண்ணிக்கையைப் பொறுத்து அறையின் தரவரிசை தீர்மானிக்கப்படுகிறது, அதிர்ஷ்டப் பரிசுகள், காயின்களின் மதிப்பில் 20% மட்டுமே கணக்கிடப்படும்."])},viewLimit:n=>{const{normalize:r}=n;return r(["Lv.10 அல்லது அதற்கு மேலானதை மட்டுமே பார்க்க முடியும்."])},statementLang:n=>{const{normalize:r}=n;return r(["இந்த நிகழ்வு Google Play உடன் இணைக்கப்படவில்லை. அனைத்து உரிமைகளும் இந்த பயன்பாட்டிற்கு ஒதுக்கப்பட்டுள்ளன."])},statementIosLang:n=>{const{normalize:r}=n;return r(["இந்த நிகழ்வு Apple Inc. உடன் தொடர்புடையதல்ல. அனைத்து உரிமைகளும் இந்த பயன்பாட்டிற்கு ஒதுக்கப்பட்டுள்ளன."])}};export{n as default};
